import {ChartCard} from '@github-ui/chart-card'
import type {ChartCardProps} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'
import {ScreenWidth, type ChartWidth} from './utils/Utility'

const LEGEND_FOCUS_OFFSET = 12

interface ColumnChartData {
  id: string
  label: string
  startDate?: string
  endDate?: string
  values: {
    [key: string]: number
  }
}

interface ColumnChartPayload {
  startDate?: string
  endDate?: string
  data: ColumnChartData[]
}

interface ColumnChartProps {
  payload: ColumnChartPayload
  title: string
  description?: string
  xAxisTitle?: string
  yAxisTitle?: string
  columnColours?: string[]
  yAxisOptions?: Highcharts.YAxisOptions
  chartWidth?: ChartWidth
  stacked?: boolean
  size?: ChartCardProps['size']
  headingLevel?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
  visibleChartOptions?: boolean
}

function ColumnChart({
  payload,
  title,
  description,
  xAxisTitle,
  yAxisTitle,
  columnColours,
  yAxisOptions,
  chartWidth = 'full',
  stacked = false,
  size = 'medium',
  headingLevel = 'h2',
  visibleChartOptions = true,
}: ColumnChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const {series, hasDateValues, categories} = computeChartData(payload, columnColours, stacked, yAxisTitle)
  const primaryYAxisOptions = {
    min: 0,
    reversedStacks: false,
    ...yAxisOptions,
  }

  return (
    <div className="height-full">
      <ChartCard
        size={size}
        border
        padding="normal"
        visibleControls={false}
        visibleChartOptions={visibleChartOptions}
        className="width-full height-full"
      >
        <ChartCard.Title as={headingLevel}>{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle={xAxisTitle ?? ''}
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          xAxisOptions={{
            gridLineWidth: 0,
            ...(hasDateValues ? {labels: {format: '{value:%b %d}'}} : {}),
            minPadding: 0,
            maxPadding: 0,
            ...(hasDateValues ? {type: 'datetime'} : {type: 'category', categories}),
            ...(hasDateValues ? {tickPositions: getTickPositions(payload.data, chartWidth)} : {}),
          }}
          yAxisOptions={primaryYAxisOptions}
          type="column"
          plotOptions={{
            column: {
              pointPadding: 0.05,
              groupPadding: 0.05,
              borderWidth: 0,
              borderRadius: 0,
            },
          }}
          tooltipOptions={{
            shared: true,
            useHTML: true,
            formatter: tooltipFormatter(yAxisTitle?.toLowerCase()),
          }}
          overrideOptionsNotRecommended={{
            // Prevent accessibility related landmarks issues by ensuring unique element roles
            accessibility: {
              landmarkVerbosity: 'one',
              series: {
                describeSingleSeries: true,
              },
              keyboardNavigation: {
                order: ['legend', 'series'],
              },
            },
            chart: {
              // Fixes an accessibility issue with the keyboard focus indicator on legend labels being clipped at
              // the top by providing adequate spacing
              spacingTop: 8,
            },
            legend: {
              align: 'left',
              verticalAlign: 'top',
              layout: 'horizontal',
              reversed: false,
              alignColumns: false,
              x: LEGEND_FOCUS_OFFSET,
              y: LEGEND_FOCUS_OFFSET,
            },
            responsive: {
              rules: [
                {
                  condition: {
                    minWidth: ScreenWidth.small,
                  },
                  chartOptions: {
                    xAxis: {
                      labels: {
                        rotation: hasDateValues ? -45 : 0,
                      },
                    },
                  },
                },
                {
                  condition: {
                    maxWidth: ScreenWidth.small,
                  },
                  chartOptions: {
                    chart: {
                      spacingRight: 10,
                      spacingLeft: 10,
                      spacingBottom: hasDateValues ? 10 : 0,
                    },
                    xAxis: {
                      // Showing all tick positions at this screen width makes the labels on this axis unreadable.
                      // Setting `tickPositions` to undefined allows us to set `tickInterval` without it being
                      // overridden by `tickPositions`.
                      tickPositions: undefined,
                      tickInterval: hasDateValues ? 2 : 1, // Shows every other date
                      labels: {
                        autoRotation: [-45, -90],
                      },
                    },
                  },
                },
              ],
            },
          }}
        />
      </ChartCard>
    </div>
  )
}

function formatAccessibleChartValue(value: number, unit?: string) {
  const formattedValue = value.toLocaleString()

  return unit === '%' ? `${formattedValue}%` : `${formattedValue} ${unit ?? ''}`.trim()
}

function getStackedBarFocusPoint(
  dataPoint: ColumnChartData,
  metrics: string[],
  hasDateValues: boolean,
  focusSeriesName: string,
  unit?: string,
) {
  const timestamp = new Date(dataPoint.endDate ?? dataPoint.startDate ?? 0).getTime()
  const total = metrics.reduce((sum, metric) => sum + (dataPoint.values?.[metric] ?? 0), 0)
  const totalDescription = `${focusSeriesName}: ${formatAccessibleChartValue(total, unit)}`
  const segmentDescription = metrics
    .map(metric => `${metric}: ${formatAccessibleChartValue(dataPoint.values?.[metric] ?? 0, unit)}`)
    .join(', ')

  return {
    ...(hasDateValues ? {x: timestamp} : {}),
    y: total,
    accessibility: {
      description: [dataPoint.label, totalDescription, segmentDescription].filter(Boolean).join('. '),
    },
  }
}

function computeChartData(payload: ColumnChartPayload, columnColours?: string[], stacked = false, yAxisTitle?: string) {
  const hasDateValues = payload.data.some(d => d.endDate)
  const categories = !hasDateValues ? payload.data.map(d => d.label) : []
  const metrics = Object.keys(payload.data[0]?.values ?? [])
  const hasStackedBarFocusSeries = stacked && metrics.length > 1

  const series: Highcharts.SeriesOptionsType[] = [...metrics].map(metric => ({
    name: metric,
    data: hasDateValues
      ? payload.data.map(d => [new Date(d.endDate ?? d.startDate ?? 0).getTime(), d.values?.[metric] ?? 0])
      : payload.data.map(d => d.values?.[metric] ?? 0),
    type: 'column' as const,
    color: columnColours?.[metrics.indexOf(metric)],
    ...(stacked && {stacking: 'normal' as const}),
    ...(hasStackedBarFocusSeries && {accessibility: {keyboardNavigation: {enabled: false}}}),
  }))

  if (hasStackedBarFocusSeries) {
    const yAxisUnit = yAxisTitle?.trim().toLowerCase()
    const stackedBarFocusSeriesName = yAxisUnit ? `Total ${yAxisUnit}` : 'Total'
    const stackedBarFocusData = payload.data.map(dataPoint =>
      getStackedBarFocusPoint(dataPoint, metrics, hasDateValues, stackedBarFocusSeriesName, yAxisUnit),
    )

    series.push({
      name: stackedBarFocusSeriesName,
      data: stackedBarFocusData,
      type: 'column' as const,
      color: 'rgba(0, 0, 0, 0)',
      grouping: false,
      minPointLength: 8,
      showInLegend: false,
      includeInDataExport: false,
      custom: {hideFromTooltip: true},
    })
  }

  return {series, hasDateValues, categories}
}

export default ColumnChart
