import {InfoButton} from './InfoButton'

interface ImpactInfoButtonProps {
  isEnterprise?: boolean
}

export function ImpactInfoButton({isEnterprise = true}: ImpactInfoButtonProps) {
  const entityText = isEnterprise ? 'enterprise' : 'organization'

  return (
    <InfoButton ariaLabel="Copilot impact dashboard info" title="How to use this dashboard">
      <InfoButton.Description role="definition" ariaLabel="Copilot impact purpose">
        Understand how deeply Copilot is being adopted across your {entityText} and identify highest-leverage
        opportunities to increase your users&apos; output and impact.
      </InfoButton.Description>
      <InfoButton.Link
        href="https://docs.github.com/en/copilot/reference/copilot-usage-metrics"
        ariaLabel="Learn how Copilot metrics are calculated"
      >
        How are these metrics calculated?
      </InfoButton.Link>
    </InfoButton>
  )
}
