import {useEffect} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import type {CopilotUsageRouteResponse} from '../types/copilot-usage-route-types'

type CanonicalQueryParams = CopilotUsageRouteResponse['canonicalQueryParams']

const ALLOWED_PERIODS = new Set(['7d', '14d', '28d'])

export function useQuerySanitizer(canonicalQueryParams: CanonicalQueryParams | undefined) {
  const canonicalPeriod = canonicalQueryParams?.period
  const [, setSearchParams] = useSearchParams()

  useEffect(() => {
    if (!canonicalPeriod) return

    setSearchParams(
      params => {
        for (const [key] of params.entries()) {
          if (key !== 'period') {
            params.delete(key)
          }
        }

        const currentPeriod = params.get('period')
        if (!currentPeriod || !ALLOWED_PERIODS.has(currentPeriod)) {
          if (canonicalPeriod) {
            params.set('period', canonicalPeriod)
          }
        }

        return params
      },
      {replace: true, preventAutofocus: true},
    )
  }, [setSearchParams, canonicalPeriod])
}
